#!/usr/bin/env python3
"""
Round 197o (culprits), 14 October 2026. Needs round 196o.

The Moon and Mars views, from NASA's Eyes.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 197o (14 October)\n\nNeeds round 196o (guards on its heading). Tiles patch round197o_tiles.py\nbeside it (scripts/bodies.py). No app.js?v= bump.\n\n- The Moon and Mars (asked 14 October): while NASA\'s Eyes is showing, Moon\n  and Mars buttons sit under Back to the map. Each opens map/bodies.html in\n  a frame over Eyes (#bodyFrame); "Solar system" closes it back to Eyes, and\n  Back to the map closes both. The page also works on its own\n  (bodies.html#moon, #mars).\n- bodies.html: Leaflet in plate carree (L.CRS.EPSG4326) over NASA Moon Trek\n  (LRO WAC mosaic, zooms 0-8) and Mars Trek (Viking MDIM 2.1 colour, 0-7,\n  real colour as the owner asked) tiles, read live from trek.nasa.gov. Tile\n  URLs are from each layer\'s WMTSCapabilities.xml (.jpg, default028mm);\n  not seen loading from the sandbox (trek.nasa.gov is blocked there).\n- Layers, from culprits-tiles-more bodies/ (scripts/bodies.py), every field\n  as given, nothing filtered:\n  Moon: LROC anthropogenic objects (PDS, public domain under LROC\'s terms;\n  credit NASA/GSFC/ASU, Wagner et al. 2017); Wikipedia\'s list of artificial\n  objects on the Moon (orbs sized by the kg column, area to mass; CC BY-SA);\n  NASA\'s nine Artemis III regions, at the IAU centre of the feature each is\n  named after (NASA published only a picture; the box says so; regions at\n  the same feature share a mark); IAU names (USGS gazetteer), more as you\n  zoom in.\n  Mars: Wikipedia\'s list; Perseverance and Curiosity routes and stops, LIVE\n  from NASA/JPL\'s MMGIS JSON (mars.nasa.gov/mmgis-maps/), falling back to\n  the daily copy in bodies/rovers/ if the browser is refused; IAU names.\n  Rows with no position are listed under the notes.\n- Not on the map yet: Mars\'s 47 candidate human landing zones (the only\n  copy with coordinates, OpenPlanetary\'s on CARTO, states no licence: asked\n  the owner); spacecraft orbiting the Moon; a south-pole view (Trek\'s polar\n  layer names not found).\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round197o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 196o" not in h.read_text(encoding="utf-8"):
        sys.exit("round197o: round 196o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round197o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/test.mjs", check=False)
            pathlib.Path("map/bodies.html").unlink(missing_ok=True)
            sys.exit("round197o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round197o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
